<section class="panel"><div class="panel-head"><h2>Riwayat {{ $kind }}</h2><span class="help">{{ $items->total() }} catatan</span></div><div class="table-wrap"><table><thead><tr><th>Tanggal / pengirim</th><th>Kelompok</th><th>Keterangan</th><th>Status</th><th>{{ auth()->user()->role==='mentor'?'Validasi':'Catatan mentor' }}</th></tr></thead><tbody>@forelse($items as $x)<tr><td><strong>{{ $x->date }}</strong><small>{{ $x->author }}</small></td><td>{{ $x->group_name }}</td><td class="description">{{ $x->description }}</td><td><span class="badge {{ $x->status }}">{{ ucfirst($x->status) }}</span>@if($x->reviewed_at)<small>{{ $x->reviewed_at }}</small>@endif</td><td>@if(auth()->user()->role==='mentor')<form class="review-form" method="post" action="/{{ $kind }}/{{ $x->id }}/validasi">@csrf @method('PUT')<select name="status" aria-label="Hasil validasi"><option value="disetujui" @selected($x->status==='disetujui')>Disetujui</option><option value="ditolak" @selected($x->status==='ditolak')>Ditolak</option></select><input name="feedback" aria-label="Catatan mentor" value="{{ $x->feedback }}" placeholder="Wajib jika ditolak"><button type="submit">Simpan validasi</button></form>@else {{ $x->feedback?:'—' }} @endif</td></tr>@empty<tr><td colspan="5" class="empty">Belum ada catatan {{ $kind }} untuk ditampilkan.</td></tr>@endforelse</tbody></table></div><div class="pagination">{{ $items->links() }}</div></section>@endsection